// Normalize the backend run.completed event into one email item.
// Webhook input: { headers, params, query, body } (n8n webhook node).
// Manual trigger input: {} - a demo event is produced so the SMTP path can be
// verified end to end from the editor without the backend.
const incoming = $input.first()?.json ?? {};
const isWebhook =
  Object.prototype.hasOwnProperty.call(incoming, 'body') ||
  Object.prototype.hasOwnProperty.call(incoming, 'headers');
const body =
  isWebhook && incoming.body && typeof incoming.body === 'object' && !Array.isArray(incoming.body)
    ? incoming.body
    : {};

const pick = (...values) =>
  values.find((value) => value !== undefined && value !== null && String(value).trim() !== '') ?? '';
const str = (value, fallback = '') =>
  value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
const int = (value) => {
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? Math.trunc(number) : 0;
};

const nowIso = $now.toISO();

// Required deployment configuration (see deploy/n8n/workflows/README.md).
// The actual SMTP transport lives in the n8n 'smtp' credential; these names are
// validated here and used for From/To so a misconfigured deployment fails
// loudly instead of sending mail to an empty address.
const smtpHost = $env.SMTP_HOST ?? '';
const smtpPort = $env.SMTP_PORT ?? '';
const smtpUser = $env.SMTP_USER ?? '';
const smtpPass = $env.SMTP_PASS ?? '';
const mailFrom = $env.MAIL_FROM ?? '';
const mailTo = $env.MAIL_TO ?? '';

const missingEnv = [];
if (!smtpHost) missingEnv.push('SMTP_HOST');
if (!smtpPort) missingEnv.push('SMTP_PORT');
if (!smtpUser) missingEnv.push('SMTP_USER');
if (!smtpPass) missingEnv.push('SMTP_PASS');
if (!mailFrom) missingEnv.push('MAIL_FROM');
if (!mailTo) missingEnv.push('MAIL_TO');

let event;
let runId;
let profession;
let status;
let message;
let runType;
let degradedReason;
let nodesCount;
let evidenceCount;
let approvedEvidenceCount;
let sourcesCount;
let startedAt;
let finishedAt;

if (isWebhook) {
  event = str(pick(body.event));
  runId = str(pick(body.run_id));
  profession = str(pick(body.profession), '(не указана)');
  status = str(pick(body.status), 'done');
  message = str(pick(body.message), 'Данные собраны, анализ обновлён');
  runType = str(pick(body.type), 'batch');
  degradedReason = str(body.degraded_reason);
  nodesCount = int(body.nodes_count);
  evidenceCount = int(body.evidence_count);
  approvedEvidenceCount = int(body.approved_evidence_count);
  sourcesCount = int(body.sources_count);
  startedAt = str(body.started_at);
  finishedAt = str(body.finished_at);
} else {
  event = 'run.completed';
  runId = 'manual-' + Date.now();
  profession = 'Тестовая профессия';
  status = 'done';
  message = 'Данные собраны, анализ обновлён (ручной тест SMTP)';
  runType = 'batch';
  degradedReason = '';
  nodesCount = 0;
  evidenceCount = 0;
  approvedEvidenceCount = 0;
  sourcesCount = 0;
  startedAt = nowIso;
  finishedAt = nowIso;
}

const problems = [];
if (missingEnv.length > 0) {
  problems.push('Missing environment variable(s): ' + missingEnv.join(', '));
}
if (event !== 'run.completed') {
  problems.push('Unexpected event ' + JSON.stringify(event) + ' (expected run.completed)');
}
if (!runId) {
  problems.push('Missing run_id');
}

// The backend outbox is at-least-once: skip a run_id that was already emailed.
// The map is persisted in the n8n global static data and written only after a
// successful send by the "Remember run_id" node.
const staticData = $getWorkflowStaticData('global');
const seen =
  staticData.notifiedRunIds && typeof staticData.notifiedRunIds === 'object'
    ? staticData.notifiedRunIds
    : {};
const retentionMs = 7 * 24 * 60 * 60 * 1000;
const cutoff = Date.now() - retentionMs;
for (const key of Object.keys(seen)) {
  if (!(Number(seen[key]) > cutoff)) delete seen[key];
}
staticData.notifiedRunIds = seen;
if (runId && seen[runId]) {
  problems.push(
    'Duplicate run_id ' + runId + ' already notified at ' + new Date(seen[runId]).toISOString(),
  );
}

return [
  {
    json: {
      event,
      run_id: runId,
      profession,
      status,
      message,
      type: runType,
      degraded_reason: degradedReason,
      nodes_count: nodesCount,
      evidence_count: evidenceCount,
      approved_evidence_count: approvedEvidenceCount,
      sources_count: sourcesCount,
      started_at: startedAt,
      finished_at: finishedAt,
      received_at: nowIso,
      mail_to: mailTo,
      is_webhook: isWebhook,
      skip_reason: problems.join('; '),
    },
  },
];

