// Persist the delivered run_id so an at-least-once redelivery does not email twice.
// The email node outputs the SMTP response (no run_id), so read the normalized item.
const data = $getWorkflowStaticData('global');
const seen =
  data.notifiedRunIds && typeof data.notifiedRunIds === 'object' ? data.notifiedRunIds : {};
const runId = String($('Normalize payload').item.json.run_id ?? '');
if (runId) seen[runId] = Date.now();
data.notifiedRunIds = seen;
return [{ json: { ...$json, run_id: runId, dedupe_recorded: Boolean(runId) } }];
